  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ulike.com/pages/ulike-affiliate-program', 'official_site', 'affiliate', 'Ulike''s own affiliate page invites affiliates, agencies, content creators and individuals to promote its IPL devices: up to 20% commission per sale, 30-day cookie, completely free to join, applications reviewed within 2-3 business days, and certified affiliates receive free products for review. The page publishes affiliate@ulike.com for program questions and states top affiliates earn $15,000 each month.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/33267', 'affiliate_network', 'affiliate', 'Ulike''s Awin merchant profile lists premium commissions of 8%-20% per sale plus performance bonuses, consistent with the brand page''s up-to-20% figure; the recorded rate is the 20% top of that published range. No earnings-cap statement appears on either page, so the cap is recorded as unknown.', 'publicly_reported', now());
