  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 17, 13, 9, 5, '{"compensation": "Published range of 8%-20% per sale via Awin with the brand page confirming up to 20% and a 30-day cookie; no cap statement found, so the cap stays unknown.", "contact_access": "A dedicated affiliate email (affiliate@ulike.com) is published on the program page, plus an open application.", "credibility": "Founded 2013; claims #1 global IPL device sales and 7M+ users on its own program page.", "niche_fit": "IPL hair-removal devices are a core beauty-creator niche with heavy TikTok/UGC demand.", "opportunity_availability": "Free online application on the brand''s own page, reviewed within 2-3 business days.", "ugc_evidence": "The brand''s own page explicitly recruits content creators and gives certified affiliates free products for review."}'::jsonb);
