  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://flutterhabit.com/pages/affiliate-sign-up', 'official_site', 'ugc_collab', 'FlutterHabit''s own collab page runs three creator routes: Flutter Bestie Ambassadors (creators with 1K+ followers; free products bi-monthly and content featured on brand socials), Flutter Sweetheart Affiliates (15% commission on every sale through a personal link or code, plus regular product restocks), and a Campus Club with commission opportunities. The page prints the brand''s address: 7811 Lemona Ave, Van Nuys, California 91405.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/flutterhabit/', 'affiliate_network', 'affiliate', 'LinkClicky''s directory (last updated March 10, 2024) lists a separate FlutterHabit program on Impact at 5% per sale and 5% per recurring subscription. That conflicts with the 15% published on the brand''s current own page, so no single commission rate is recorded.', 'publicly_reported', now());
