  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 10, 11, 9, 4, '{"compensation": "The brand''s own page publishes 15% commission for Sweetheart Affiliates, but a directory listing for its Impact program says 5% \u2014 conflicting, so the rate is null and compensation is scored mid-range.", "contact_access": "Public application routes (Typeform/Workable) for each program on the official page; no public email found.", "credibility": "DTC brand founded in 2019 with a published US business address in Van Nuys, California.", "niche_fit": "DIY lash clusters are a highly demonstrable, creator-led beauty niche.", "opportunity_availability": "Applications are publicly open, including to creators with as few as 1K followers for the ambassador tier.", "ugc_evidence": "Three structured creator programs on the brand''s own page, with ambassador content featured across the brand''s social platforms."}'::jsonb);
