  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.skinvirtue.com.au/collections/skin-virtue-b2c-affiliate-program', 'official_site', 'affiliate', 'Skin Virtue''s own B2C Affiliate Program page states the program runs on Impact and is designed for bloggers, influencers and digital marketers: 20% commission on every sale generated through a unique affiliate link, marketing materials including social media content, a real-time reporting dashboard and prompt payouts, with sign-up through the Impact portal. No earnings-cap statement appears, so the cap is recorded as unknown.', 'verified', now());
