  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 8, 6, 8, 4, '{"compensation": "Four conflicting published figures (4%, 5%, 8%, up to 15%) \u2014 rate null; compensation scores below mid-range.", "contact_access": "A general support email (support@nood.com) is published on the brand''s own product pages; no creator-specific contact.", "credibility": "Established DTC device brand with a 90-day guarantee and US warehouse fulfillment.", "niche_fit": "At-home IPL hair removal is a proven beauty-device niche for creator demonstrations and progress content.", "opportunity_availability": "Free to join through network programs per directory listings.", "ugc_evidence": "Programs run through multiple networks, but no brand-run ambassador or UGC program was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Dionis Goat Milk Skincare', 'https://dionisgmskincare.com', 'Goat-milk skincare brand begun in 1982 on a small goat farm in Pennsylvania by founder Kate Crosby, selling hand creams, lotions, lip care and body care through its own site and retailers including Target, Ulta, Macy''s and Amazon.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://compareepc.com/skincare-affiliate-programs/.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/skincare-affiliate-programs/', 'affiliate_network', 'affiliate', 'CompareEPC''s skincare affiliate index lists Dionis Goat Milk Skincare on Impact at 15% commission (EPC $3.02). No earnings-cap statement was found, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://newproductevents.com/wp-content/uploads/2026/02/Dionis-Inspire-Hand-Cream-Set-Fact-Sheet.pdf', 'official_site', 'affiliate', 'Dionis''s own 2025 press kit (Inspire hand cream fact sheet) prints ''Affiliate Impact ID: #43351'', corroborating the Impact program, and lists availability at DionisGMSkincare.com and select retailers including Amazon, Macy''s, Target and Ulta.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://rootedshop.com/pages/dionis-goat-milk-skincare', 'listing', 'general', 'Rooted Shop''s brand page states Dionis Goat Milk Skincare began in 1982 on a small goat farm in Pennsylvania, where founder Kate Crosby started making goat milk soap by hand.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 8, 13, 4, 8, 4, '{"compensation": "15% on Impact per the network index \u2014 a solid published rate, single primary source.", "contact_access": "No public creator contact found; joining is via the Impact network.", "credibility": "Heritage brand dating to 1982 with national retail distribution (Target, Ulta, Macy''s, Amazon).", "niche_fit": "Goat-milk hand and body care is a narrower skincare niche than facial skincare, but fits natural-beauty creators.", "opportunity_availability": "Application through Impact per the network index and the brand''s published Impact affiliate ID.", "ugc_evidence": "An Impact affiliate program exists (corroborated by the brand''s press kit), but no ambassador or UGC program evidence was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Mott & Bow', 'https://www.mottandbow.com', 'Direct-to-consumer premium basics brand founded in New York, built on denim expertise and known for jeans, tees and sweaters sold at ''fair prices'' by cutting out middlemen. Its affiliate program is free for publishers to join through Pepperjam (Ascend by Partnerize) and sends affiliates gifted product packages.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Pepperjam (Ascend by Partnerize)', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.mottandbow.com/en-tl/pages/affiliate-program.', 'https://www.mottandbow.com/en-tl/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mott & Bow Affiliate Program (via Pepperjam/Ascend)', 'https://www.mottandbow.com/en-tl/pages/affiliate-program', 'https://www.mottandbow.com/en-tl/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.mottandbow.com/en-tl/pages/affiliate-program', 'official_site', 'affiliate', 'Mott & Bow''s own affiliate page: free to sign up as a publisher, ''Attractive commission structure of up to 30%'', exclusive offers for readers, gifted packages of product for affiliates, and joining instructions via Pepperjam (signup at Ascend) — search ''Mott & Bow'' under Find New Advertisers and click Apply. Testimonials on the page come from creator affiliates (travel and menswear blogs). The 30% figure is published only as an ''up to'' ceiling, not a flat rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/mott-bow/', 'affiliate_network', 'affiliate', 'Lasso''s affiliate directory lists the Mott & Bow program at 20% per sale with a 14-day cookie, in the Fashion/T-Shirt categories.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://theaffiliatemonkey.com/affiliate/mott-bow-affiliate-program/', 'listing', 'compensation', 'The Affiliate Monkey reports the program is hosted on Pepperjam with typical commissions of 10-15% per sale and up to 30% for top performers. Because published figures conflict (20% flat at Lasso vs 10-15% typical here vs an ''up to 30%'' ceiling on the brand''s own page), commission_rate is left null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 12, 8, 9, 5, '{"niche_fit": "Premium denim and basics are core fashion-creator territory (jeans fit content, menswear and everyday style).", "ugc_evidence": "The brand''s own program page showcases working creator affiliates and sends affiliates gifted product packages to create content with.", "compensation": "A published ''up to 30%'' ceiling on the brand''s own page and a 20% listing at Lasso suggest strong pay, but sources conflict on the standard rate, so this is mid-band rather than top.", "contact_access": "A public program page with step-by-step joining instructions, but no published affiliate email \u2014 application runs through the network.", "opportunity_availability": "Free, open publisher signup through Pepperjam/Ascend per the brand''s own page.", "credibility": "Established DTC brand operating since 2014 with a large direct customer base."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sorel', 'https://www.sorel.com', 'Footwear brand founded in 1962 (now part of Columbia Sportswear) known for fashion-forward winter and all-season boots, sneakers and sandals for women, men and kids, including the Caribou and Joan of Arctic lines. Its affiliate program explicitly welcomes content partners and is managed by Acceleration Partners.', 'United States', 'published') returning id into bid;
