  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://linkclicky.com/affiliate-program/sorel/.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sorel Affiliate Program (CJ Affiliate)', null, 'https://linkclicky.com/affiliate-program/sorel/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/sorel/', 'affiliate_network', 'affiliate', 'LinkClicky''s affiliate directory lists the Sorel program on CJ Affiliate at 8% commission per sale (page last updated March 11, 2024).', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.accelerationpartners.com/resources/sorel-selects-acceleration-partners/', 'listing', 'affiliate', 'Acceleration Partners, the agency that took over management of SOREL''s affiliate program, states the program provides up to 10% commission per sale and a 30-day cookie window, and that ''if you''re a content partner, loyalty affiliate, or mass media site, SOREL welcomes your application.''', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/sorel-2/', 'listing', 'compensation', 'Lasso lists Sorel at 10% per sale with a 21-day cookie. Published rates conflict (8% at LinkClicky/Post Affiliate Pro vs up to 10% from the program manager and Lasso) and cookie windows differ (21 vs 30 days), so commission_rate is left null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 10, 6, 8, 5, '{"niche_fit": "Fashion-forward boots and seasonal footwear are a staple of style and winter-content creators.", "ugc_evidence": "The program manager explicitly recruits content partners, but there is no public creator/ambassador program page on the brand''s own site.", "compensation": "Published figures of 8% to up to 10% per sale exist but conflict between directories, so the rate is unverified and scored mid-band.", "contact_access": "No published affiliate email or own-site application page found; joining runs through the CJ network listing.", "opportunity_availability": "Open network program that publicly welcomes content partner applications.", "credibility": "Heritage footwear brand founded in 1962 and owned by Columbia Sportswear, sold through major retailers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Indochino', 'https://www.indochino.com', 'Canadian made-to-measure menswear company selling custom suits, shirts, chinos, blazers and overcoats online and through showrooms. Its affiliate page offers commission on every product sale with a 30-day tracking cookie and publishes a program contact email.', 'Canada', 'published') returning id into bid;
