  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.indochino.com/become-an-affiliate?currency=AUD', 'official_site', 'affiliate', 'Indochino''s own ''Become an affiliate'' page states affiliates earn 2% commission on every product sale, with a 30-day tracking cookie, dynamic banners and private commission offers, and gives the program contact email Indochino@OPMpros.com (OPMpros is its affiliate management agency).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/indochino/', 'affiliate_network', 'compensation', 'Lasso''s directory lists the Indochino program at 12% per sale with a 30-day cookie — a direct conflict with the 2% published on the brand''s own affiliate page, so commission_rate is left null and the conflict is documented here.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 6, 11, 7, 5, '{"niche_fit": "Custom suits and menswear are a strong fit for men''s fashion, wedding and professional-style creators.", "ugc_evidence": "A public affiliate program exists, but no dedicated creator or ambassador content program is published on the brand''s pages.", "compensation": "The brand''s own page publishes only 2%, while a directory claims 12% \u2014 the conflict and the low own-page figure keep this low.", "contact_access": "A program contact email (Indochino@OPMpros.com) is published on the brand''s own affiliate page, plus an on-site application route.", "opportunity_availability": "Public affiliate page with open application; exact network and approval terms are not stated on the page.", "credibility": "Established made-to-measure retailer founded in Canada with showrooms across North America."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('NA-KD', 'https://www.na-kd.com', 'Swedish global online fashion retailer selling trend-led women''s clothing, shoes and accessories, heavily driven by influencer collaborations and social-first drops. Its affiliate program pays a percentage of each sale tracked over a 30-day cookie.', 'Sweden', 'published') returning id into bid;
