  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.influencerrate.com/affiliate-program/na-kd', 'listing', 'affiliate', 'InfluencerRate''s program page states NA-KD commissions typically range from 5-10% of the sale value with a 30-day tracking cookie, and that the program is free to join. Only a range is published (no single rate), so commission_rate is left null.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 9, 5, 8, 4, '{"niche_fit": "Trend-driven women''s fashion built around influencer drops \u2014 squarely in the fashion UGC niche.", "ugc_evidence": "NA-KD is known for influencer collaboration collections, but no open creator application page was found on its own site.", "compensation": "Two directories agree on a 5-10% per-sale range, but no single published rate or own-page terms could be verified.", "contact_access": "No published affiliate contact or own-site program page found; discovery runs through third-party directories.", "opportunity_availability": "Program is reported as free to join with a standard network-style application.", "credibility": "Large Swedish online fashion retailer with international shipping and a substantial social following."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Dolce Vita', 'https://www.dolcevita.com', 'New York-founded women''s footwear brand (part of Steve Madden) selling trend-driven heels, boots, sandals and sneakers through its own site and major retailers. Its affiliate program runs on Rakuten Advertising.', 'United States', 'published') returning id into bid;
