  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/dolcevita-com/', 'listing', 'compensation', 'Lasso lists the DolceVita.com program at 6.4% per sale with a 7-day cookie, and Shopper reports 2.56% — three conflicting published rates (2% / 2.56% / 6.4%), so commission_rate is left null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 5, 5, 8, 4, '{"niche_fit": "Women''s trend footwear is a reliable fashion-creator category, especially for outfit and occasion content.", "ugc_evidence": "A standard network affiliate program exists; no public creator or ambassador program was found on the brand''s own pages.", "compensation": "Published rates are low and conflict across directories (2%, 2.56%, 6.4%), so this scores at the low end.", "contact_access": "No published affiliate contact or own-site program page found; joining runs through the Rakuten network listing.", "opportunity_availability": "Open network program on Rakuten Advertising with standard publisher application.", "credibility": "Established footwear label owned by Steve Madden and distributed through major US retailers."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Uniplaces', 'https://www.uniplaces.com', 'Lisbon-founded online marketplace for student and mid-term accommodation in cities across Europe. Alongside network affiliate programs, it runs a City Explorer Ambassador program — including a paid Content Creator track for TikTok, Instagram and YouTube creators — that pays commission on every booking made with an ambassador''s code.', 'Portugal', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Tradedoubler', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.uniplaces.com/city-explorer/ambassadors/.', 'https://www.uniplaces.com/city-explorer/ambassadors/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Uniplaces City Explorer Ambassador Program (incl. Content Creator track)', 'https://www.uniplaces.com/city-explorer/ambassadors/', 'https://www.uniplaces.com/city-explorer/ambassadors/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.uniplaces.com/city-explorer/ambassadors/', 'official_site', 'affiliate', 'Uniplaces'' own Ambassador page, fetched in full: ''Commission Model — Your monthly earnings are directly linked to the paid bookings you bring in. No ceilings, no gatekeeping.'' and the FAQ states ''The more bookings you generate, the more you earn — there''s no limit.'' VERIFIED UNCAPPED on the brand''s own page. The page also states 800+ active ambassadors (a few-hundred-scale figure, so saturation stays ''unknown''), a promo code giving tenants 25% off the service fee, payment via virtual card, and a Content Creator track paying creators (2K+ engaged followers) per piece and on bookings.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliate-program.io/en/programs/uniplaces-de-tradedoubler', 'affiliate_network', 'affiliate', 'Affiliate-program.io''s network data lists a Uniplaces DE affiliate program on Tradedoubler at 11.5% per sale, showing the brand also runs conventional network affiliate programs alongside the ambassador scheme. The ambassador program itself publishes no percentage, so commission_rate is left null.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.shopper.com/partnerships/uniplaces-com-affiliate-program', 'listing', 'compensation', 'Shopper''s partnership directory reports a Uniplaces affiliate payout of 10-20% per sale (a range only, not a single verified rate).', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 13, 8, 8, 4, '{"niche_fit": "Student housing and moving-abroad content is a proven travel/study-abroad creator niche, and the program has a dedicated creator track.", "ugc_evidence": "The brand''s own page runs a Content Creator track that pays TikTok/Instagram/YouTube creators per piece plus booking commissions, with content briefs from its marketing team.", "compensation": "Earnings are verified uncapped on the brand''s own page (''No ceilings''; ''there''s no limit''), but no commission percentage is published for ambassadors, keeping this mid-band.", "contact_access": "A public application form on the program page (reviewed within five business days), but no published program email.", "opportunity_availability": "Open application; the Content Creator track asks for 2K+ engaged followers, and ambassadors must be 18+.", "credibility": "Operating since 2012 as a major European student-accommodation marketplace."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tortuga', 'https://tortuga.com', 'US travel-gear company making carry-on travel backpacks, daypacks and packing accessories designed for city travel, with average order values around $214. Its affiliate program runs on AvantLink with separate routes for website publishers and social media influencers, and top affiliates can receive gear to review.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'AvantLink', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://carlbroadbent.com/affiliate-program/affiliate-programs-for-travel-bloggers/.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tortuga Affiliate Program (AvantLink)', null, 'https://carlbroadbent.com/affiliate-program/affiliate-programs-for-travel-bloggers/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://carlbroadbent.com/affiliate-program/affiliate-programs-for-travel-bloggers/', 'listing', 'affiliate', 'Travel-blogger affiliate roundup lists Tortuga Backpacks at 10% commission with a 60-day cookie, pay-per-sale, delivered by AvantLink, with free travel gear available to test and review.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://onemorecupof-coffee.com/best-travel-accessories-affiliate-programs/', 'listing', 'affiliate', 'One More Cup of Coffee''s travel-accessories program guide independently lists Tortuga at 10% commission, 60-day cookie, run through AvantLink, noting separate options for website publishers and social media influencers and an average order value of $214.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 13, 6, 6, 4, '{"niche_fit": "Carry-on travel backpacks are a core product category for travel-gear creators and packing-content channels.", "ugc_evidence": "The program has a dedicated social-influencer route and sends sample gear to high-performing affiliates for review content.", "compensation": "Two independent directories agree on a published 10% per sale with a 60-day cookie, on premium-priced products (~$214 average order).", "contact_access": "No published affiliate email or own-site program page found; application runs through AvantLink.", "opportunity_availability": "Network application on AvantLink; one source notes traffic/domain-authority expectations for easy approval, so not fully open.", "credibility": "Well-known specialist travel-backpack brand with award-winning products and a long-running affiliate presence."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Aviasales', 'https://www.aviasales.com', 'Flight-search metasearch engine comparing fares from 1,000+ airlines and agencies. Its affiliate offer runs through the Travelpayouts network and pays partners a share of the revenue Aviasales receives from airlines and agencies on confirmed flight bookings, with lifetime attribution for bookings made in an Aviasales app installed via a partner''s marker.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Travelpayouts', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.affiliates-directory.com/websites/aviasales.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Aviasales Affiliate Offer (via Travelpayouts)', null, 'https://www.affiliates-directory.com/websites/aviasales', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliates-directory.com/websites/aviasales', 'affiliate_network', 'affiliate', 'Affiliates Directory''s 2026 review of the Aviasales offer on Travelpayouts: per Travelpayouts'' current Aviasales guidance, affiliates receive 40% of the revenue Aviasales receives from agencies and airlines on confirmed bookings — explicitly not 40% of the ticket price; Travelpayouts gives an illustrative average of about 0.88% of ticket value. Lifetime attribution applies to purchases in an Aviasales app installed with the affiliate''s marker.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/asian-affiliate-programs/', 'official_site', 'compensation', 'Travelpayouts'' own (older) program page lists Aviasales at ''up to 70% revenue share'', with a tier table of 60% below $3,500 monthly revenue and 70% above it. This conflicts with the 40%-of-revenue figure in current guidance reported by recent sources, so commission_rate is left null and the revenue-share basis is documented here instead.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 12, 12, 6, 9, 4, '{"niche_fit": "Flight search is one of the highest-intent topics in travel content; the offer is built for travel publishers and creators.", "ugc_evidence": "Travelpayouts supplies search forms, widgets and white-label tools aimed at content sites and creators, though there is no ambassador-style program.", "compensation": "A revenue-share model (share of Aviasales'' booking revenue, ~0.88% of ticket value illustratively) suits high-volume flight content, but published share figures conflict (40% current vs up to 70% older), so the rate is unverified.", "contact_access": "No brand-published affiliate contact found; everything runs through the Travelpayouts network account.", "opportunity_availability": "Open, free network signup on Travelpayouts with instant access to the Aviasales offer and tools.", "credibility": "One of the largest flight metasearch brands, anchoring the Travelpayouts network since its launch."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ye-sim', 'https://ye-sim.app', 'Travel eSIM provider selling local, regional and global data plans. Its own affiliate program pays a base 10% commission on referred users'' first, second and recurring purchases — lifetime commissions — with instant payouts from €100 and a personal account manager for partners.', null, 'published') returning id into bid;
