  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ye-sim Affiliate Program', 'https://ye-sim.app/affiliate-program/', 'https://ye-sim.app/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ye-sim.app/affiliate-program/', 'official_site', 'affiliate', 'Ye-sim''s own affiliate page, fetched in full: free to join with setup under a minute; ''Earn from 10% on every purchase''; the default base commission is 10% for the first purchase, 10% for the second purchase and 10% for recurring purchases, described as lifetime commissions on referred users; rates can be customized by volume; instant payouts from €100; the page states 1000+ bloggers, creators and travel experts already monetize with it (a thousand-scale claim, so saturation stays ''unknown'' rather than low). No earnings-cap statement appears on the page, so the cap is honestly ''unknown''.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ye-sim.app/affiliate-program/', 'official_site', 'ugc_collab', 'The same page explicitly welcomes influencers and content makers (''Ideal for influencers with a following in travel or technology''; ''Perfect for creators who want to offer their followers seamless mobile access'') and provides marketing assets, a dashboard and a personal account manager.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 13, 7, 9, 3, '{"niche_fit": "Travel eSIMs are a natural, repeatable recommendation for travel creators; Ye-sim targets travel audiences specifically.", "ugc_evidence": "The brand''s own program page explicitly recruits influencers and content makers and supplies marketing assets for them.", "compensation": "Published on the brand''s own page: 10% base on first, second and recurring purchases with lifetime attribution \u2014 recurring revenue, though not a high headline rate.", "contact_access": "Open program page with a personal account manager promised to partners, but no published contact email.", "opportunity_availability": "Free to join, setup in under a minute, no minimum audience stated on the page.", "credibility": "Smaller, newer eSIM brand; claims \u20ac1M+ paid to partners on its own page but has limited third-party coverage."}'::jsonb);
