  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 7, 6, 8, 4, '{"niche_fit": "Hostels and budget youth accommodation are a core topic for backpacker and student-travel creators.", "ugc_evidence": "The own-site program page explicitly names content as a channel (''through your website, app, or content''), but there is no creator-specific program or ambassador scheme.", "compensation": "The program promises ''competitive commissions'' on confirmed bookings but publishes no rate anywhere found, so this stays low-mid.", "contact_access": "A public program page with an affiliate team mentioned, but no published contact email or application form details in the fetched page.", "opportunity_availability": "Public program page inviting websites, apps and content creators to integrate via links, widgets or API.", "credibility": "Part of the Hostelworld Group with over 1 million bed nights sold, per its own program page."}'::jsonb);
