  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partnerprogram.truelycereal.com/terms', 'official_site', 'affiliate', 'Truely Cereal''s own partner-program terms (read in full Nov 21, 2026) set tiered commissions on the subtotal of completed, non-refunded sales: Starter 15% by default, Performer 17% at 30 lifetime sales, Top 20% at 100, and Athlete 22.5% at 250. Partners give their audience 10% off a first order via a unique code; payouts are monthly via Zelle or Interac with a $20 minimum, open to US and Canadian residents aged 18+. The terms make no earnings-cap statement, so the cap is recorded as unknown.', 'verified', now());
