  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.1naturalway.com/affiliate', 'official_site', 'affiliate', '1 Natural Way''s own affiliate page (read Nov 21, 2026) offers a flat $5 for every valid lead, a 90-day cookie window, monthly payouts via PayPal, and free joining with a short application; it explicitly invites bloggers, influencers, lactation consultants, healthcare pros and parenting sites. The page makes no earnings-cap statement, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.1naturalway.com/affiliate', 'official_site', 'contact', 'The same official page publishes the company''s contact details — support@1naturalway.com and 4064 Technology Drive, Maumee, Ohio 43537 — and describes its offer as insurance-covered breast pumps, at-home maternal-wellness lab tests, maternity-support products and an IBCLC care team. No creator-count figures are published, so creator saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 11, 9, 13, 9, 4, '{"compensation": "A flat $5 per valid lead (not per sale) with a 90-day cookie \u2014 simple and published on the brand''s own page, though lead value is modest.", "contact_access": "Publishes a general support email and a full street address on its own affiliate page, plus the application itself \u2014 top-band contact access.", "credibility": "Established maternal-health provider with a physical Ohio headquarters and an insurance-covered product offer.", "niche_fit": "A focused maternal-health offer \u2014 a narrower niche than general wellness, but a precise fit for mom and pregnancy creators.", "opportunity_availability": "Open application on the brand''s own site, free to join with no minimums.", "ugc_evidence": "Runs its own affiliate program with a public page that explicitly recruits influencers and bloggers."}'::jsonb);
