  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/plant-therapy/', 'affiliate_network', 'affiliate', 'Lasso''s affiliate directory (read Nov 21, 2026) lists the Plant Therapy affiliate program at 7.5% per sale with a 7-day cookie and a $50 payout threshold, and its join link points to ascend.pepperjam.com, identifying the network as Pepperjam. The 7.5% rate is corroborated by multiple other directories (UpPromote, AMALinksPro, AffiliateBooster). No earnings-cap statement is published, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/plant-therapy/', 'listing', 'general', 'The same directory describes Plant Therapy as a leading essential-oils brand with USDA-certified organic oils and a KidSafe line aimed at families and wellness creators. No creator-count figures are published, so creator saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 10, 8, 9, 5, '{"compensation": "7.5% per sale is a modest but consistently reported rate across several directories; the 7-day cookie is short.", "contact_access": "Application runs through Pepperjam; no direct partnerships email is published.", "credibility": "One of the largest essential-oil brands in the US, with USDA-certified organic lines and a long retail track record.", "niche_fit": "Essential oils are a core wellness-UGC category (diffuser routines, family wellness, natural living) and Plant Therapy is one of its best-known brands.", "opportunity_availability": "Open application through Pepperjam with published terms.", "ugc_evidence": "Runs a long-standing affiliate program on Pepperjam used by wellness and yoga creators; no separate ambassador program is published."}'::jsonb);
