  insert into public.brands (name, website, description, country, status) values ('TweetDelete', 'https://tweetdelete.net', 'Online service that bulk-deletes tweets and likes by age or keyword, founded in 2011 by software developer Richard West and used by more than 5 million people; its brand-direct affiliate program pays a flat 20% per order and explicitly states there are no limits on earnings.', 'United Kingdom', 'published') returning id into bid;
