  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TweetDelete Affiliate Program', 'https://tweetdelete.net/affiliate-program/', 'https://tweetdelete.net/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tweetdelete.net/affiliate-program/', 'official_site', 'affiliate_program', 'The brand''s own affiliate page states verbatim: ''No limits on earnings or payouts'', and its FAQ answers ''What commission rate is offered?'' with ''We offer a flat 20% commission rate per order. There are no monthly limits to how much you can earn from our affiliate program.'' Terms on the page: 30-day cookie, monthly payouts by direct deposit or PayPal, no minimum payout, free to join, affiliates must be 18+ with a Twitter/X account, and referrals get a 10% discount code (example given: $99 Lifetime Plan earns $19.80).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tweetdelete.net/about-us/', 'official_site', 'official_site', 'The brand''s About page says TweetDelete was developed in 2011 by software developer Richard West, has been used by more than 5 million unique people with over 2 million continuous users, and mass-deletes tweets and likes by age or text string.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.trustpilot.com/review/tweetdelete.net', 'review', 'company_profile', 'Trustpilot''s company details for TweetDelete list the contact address 49 Gaunt Street, Lincoln LN5 7PU (a UK postcode), supporting the United Kingdom country entry.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 12, 17, 6, 9, 3, '{"niche_fit": "A focused tool for X/Twitter creators and social-media managers; narrower than a general tech product but squarely aimed at people who post for a living.", "ugc_evidence": "The affiliate page courts website owners and creators with a referral discount code and worked earnings examples, though it is not a UGC-first program page.", "compensation": "Flat 20% per order with an explicit no-limits statement on the brand''s own page, no minimum payout and monthly payments \u2014 strong, verified-uncapped terms.", "contact_access": "No public email appears on the fetched pages; contact is through the on-page affiliate application form only.", "opportunity_availability": "Free to join for anyone 18+ with a Twitter/X account; approval appears self-serve via the on-page form.", "credibility": "Operating since 2011 with a claimed 5M+ users, but a small private company and mixed public review presence, so mid-low credibility."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Surfshark', 'https://surfshark.com', 'Consumer VPN and online-security suite (VPN, antivirus, data-leak alerts, private search) founded in 2018 and operated by Surfshark B.V. in Amsterdam; its affiliate program pays 40% revenue share on new sales and explicitly courts YouTube, Facebook and X creators.', 'Netherlands', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Tune (HasOffers)', 40, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://surfshark.com/affiliate.', 'https://surfshark.com/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Surfshark Affiliate Program', 'https://surfshark.com/affiliate', 'https://surfshark.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://surfshark.com/affiliate', 'official_site', 'affiliate_program', 'The brand''s own affiliate page advertises ''Competitive 40% revenue share on new sales'', a 30-day cookie and a $100 minimum payout threshold, with a personal account manager. Its FAQ states Tune (HasOffers) is the main affiliate platform and that Surfshark can also be found on Impact Radius, Avant, CJ, AppsFlyer and Awin; it says no website is needed and names Facebook, X and YouTube as promotion channels, and notes CPA conditions can be discussed. The affiliate page itself makes no earnings-cap statement, so the cap is recorded as unknown (the separate Refer & Earn customer referral FAQ''s no-limit wording does not cover this program and was not used).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/Surfshark', 'review', 'company_profile', 'Wikipedia and company reporting describe Surfshark as a cybersecurity company founded in 2018, operated by Surfshark B.V. at Kabelweg 57, Amsterdam, Netherlands (headquarters moved from the British Virgin Islands to the Netherlands in October 2021), supporting the Netherlands country entry.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 18, 10, 8, 5, '{"niche_fit": "VPN and online security is one of the most creator-promoted technology categories, and Surfshark''s suite fits tech, privacy and lifestyle channels.", "ugc_evidence": "The program page explicitly supports creators on YouTube, Facebook and X, offers a personal account manager and is open to negotiating CPA deals.", "compensation": "40% revenue share on new sales is among the highest mainstream VPN rates, with custom CPA available; $100 payout threshold noted.", "contact_access": "Application plus a named account-manager model, but no public email address appears on the fetched page.", "opportunity_availability": "Open application and no website required; runs mainly through Tune with several network alternatives.", "credibility": "Major global consumer brand founded in 2018 with award mentions (PCMag, CNET) cited on its own affiliate page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Incogni', 'https://incogni.com', 'Personal-data removal service created by the Surfshark team that requests deletion from 420+ data brokers; its affiliate program starts at 40% revenue share with tiered rates for higher-volume partners and a dedicated affiliate manager.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 40, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://incogni.com/affiliate.', 'https://incogni.com/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Incogni Affiliate Program', 'https://incogni.com/affiliate', 'https://incogni.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://incogni.com/affiliate', 'official_site', 'affiliate_program', 'The brand''s own affiliate page states: ''Starting at a 40% revenue-based commission'' with ''the potential to earn up to $100 per CPA commission, depending on your traffic or affiliate tier'' and a standard 30-day cookie. Tiers: Verified Affiliates 40% revenue share (1-99 conversions/month), Rising Stars custom rates (100-399), Superhero Affiliates custom rates (400+). It offers a dedicated affiliate manager, a creative library and performance reports. No earnings-cap statement appears on the page, so the cap is unknown; the $100 figure is a per-conversion CPA ceiling, documented here rather than treated as a base rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://safestackpro.com/incogni-review', 'review', 'company_profile', 'Review research on Incogni''s contracts reports that since October 2023 customer agreements run through Incogni Inc., a California corporation (principal office in Los Angeles, CA), supporting the United States country entry; some directories instead list Amsterdam, reflecting the Dutch Surfshark parent. The service was created by the Surfshark team in 2021 and launched in January 2022.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://locklore.com/incogni-review/', 'review', 'review', 'Hands-on review citing the brand''s own site reports Incogni removes personal data from 420+ data brokers (up from 310+ previously) and operates independently of Surfshark''s VPN despite the shared parent.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 17, 9, 8, 5, '{"niche_fit": "Data-privacy removal is a heavily creator-promoted service that fits tech, privacy and general-audience channels.", "ugc_evidence": "The program provides a dedicated affiliate manager, a creative library and custom assets, and is structured around content partners.", "compensation": "40% revenue share at the entry tier with custom higher-volume tiers and CPA options up to $100 per conversion.", "contact_access": "Affiliate team reachable through the program page and support channels; no direct public email on the fetched page.", "opportunity_availability": "Open application with tiers starting at a single monthly conversion.", "credibility": "Well-known consumer brand in the Surfshark group with a large broker-removal footprint and mainstream review coverage."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('NordVPN', 'https://nordvpn.com', 'Flagship VPN service of Nord Security, provided by Panama-based nordvpn S.A.; its long-running affiliate program pays 100% on new 1-month plans and 40% on longer plans, with dedicated partnership managers for creators.', 'Panama', 'published') returning id into bid;
