  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'general', 'payments@nordvpnmedia.com', null, 'https://nordvpn.com/affiliate-guide/', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 40, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://nordvpn.com/affiliate-guide/.', 'https://nordvpn.com/affiliate-guide/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'NordVPN Affiliate Program', 'https://nordvpn.com/affiliate-guide/', 'https://nordvpn.com/affiliate-guide/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nordvpn.com/affiliate-guide/', 'official_site', 'affiliate_program', 'The brand''s own affiliate guide publishes its commission table: new sign-ups pay 100% (1-month offer) or 40% (all other offers) and renewals pay 30%. It states payouts can be sent once collected commission exceeds $100, via PayPal or wire transfer after a 40-day delay, and publishes the payments contact payments@nordvpnmedia.com. The guide describes a dedicated partnership manager, an in-house Affiliate Dashboard for tracking links, and a requirement to send content for approval at least two business days before publishing. No earnings-cap statement appears, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nordvpn.com/terms-of-service/', 'official_site', 'company_profile', 'NordVPN''s own terms of service state the service is provided by nordvpn S.A., Panama City, Panama, under Panamanian law, supporting the Panama country entry.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://en.wikipedia.org/wiki/Nord_Security', 'review', 'company_profile', 'Wikipedia describes parent company Nord Security as founded in 2012 in Lithuania by Tomas Okmanas, Eimantas Sabaliauskas and Jonas Karklys, headquartered in the Netherlands, with NordVPN as its flagship product.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 19, 11, 8, 5, '{"niche_fit": "The most creator-sponsored VPN brand in its category; fits tech, gaming, privacy and general YouTube/TikTok audiences.", "ugc_evidence": "Own guide describes partnership managers, SEO/design/CRO content support and a creator-focused approval workflow.", "compensation": "100% on new 1-month plans, 40% on longer plans and 30% renewals \u2014 top-of-market VPN terms, published in the brand''s own table.", "contact_access": "A payments email is published on the brand''s own guide and each partner gets a partnership manager.", "opportunity_availability": "Open application through the affiliate dashboard; content pre-approval is required before publishing.", "credibility": "One of the largest VPN brands worldwide, operating since 2012 under Nord Security."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Crate & Barrel', 'https://www.crateandbarrel.com', 'Major US home-furnishings retailer (Euromarket Designs, Inc., founded 1962) selling furniture, kitchen and decor; its affiliate program pays 5% per sale with a 45-day cookie, managed through Impact and other networks.', 'United States', 'published') returning id into bid;
