  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/crate-barrel/', 'listing', 'affiliate_program', 'Uppromote''s directory reports the Crate & Barrel program is managed through Impact, pays up to 5% by category, pays monthly on Net 30/60 terms via Impact, and counts content creators and home-decor bloggers among its affiliate types.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/crate-and-barrel/', 'listing', 'company_profile', 'Program materials identify the operator as Euromarket Designs, Inc. dba Crate & Barrel, Crate & Kids, CB2 and Hudson Grace, a United States retailer.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 10, 7, 8, 5, '{"niche_fit": "Core home-decor and furniture brand for home, DIY and lifestyle creators, with high average order values.", "ugc_evidence": "Directory materials list content creators and home-decor bloggers as target affiliate types, and the retailer staffs creator-tier affiliate roles from nano to mega.", "compensation": "5% per sale is modest, partly offset by expensive furniture baskets and a 45-day cookie.", "contact_access": "No public program email on the fetched pages; contact runs through the network application.", "opportunity_availability": "Joinable through Impact and other networks with standard approval.", "credibility": "Established national retailer operating since 1962 under Euromarket Designs, Inc."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Skylight', 'https://www.skylightframe.com', 'San Francisco company behind the Skylight Frame digital photo frame and the Skylight Calendar family organizer; its Awin affiliate program pays 2% per sale and up to 15% for content partners on a 90-day cookie.', 'United States', 'published') returning id into bid;
