  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Skylight Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/50821', 'https://ui.awin.com/merchant-profile/50821', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/50821', 'affiliate_network', 'affiliate_program', 'Skylight''s own Awin merchant profile states verbatim: ''Commission Rate: 2% Commission per Sale and Up to 15% for Content Partners! Cookie: 90 days'', and describes the Skylight Frame and Smart Family Calendar products. The 2% base rate is recorded; the 15% figure is a ceiling for content partners, not the base rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.skylightframe.com/policies/terms-of-service', 'official_site', 'company_profile', 'Skylight Frame''s published terms list the company at 101A Clay Street #144, San Francisco, CA 94111, supporting the United States country entry.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 14, 9, 6, 8, 4, '{"niche_fit": "Family photo frames and organizers fit parenting, family and gift-guide creators well, though the niche is narrower than general home decor.", "ugc_evidence": "The Awin profile explicitly reserves its top rate (up to 15%) for content partners, signalling a deliberate creator tier.", "compensation": "2% base is low; the up-to-15% content-partner ceiling and a generous 90-day cookie improve the picture but are not guaranteed.", "contact_access": "Application runs through Awin; no public program email appears on the fetched pages.", "opportunity_availability": "Open to join via Awin with a published merchant profile.", "credibility": "Established consumer-electronics brand selling in the US, UK, Canada and Australia from a San Francisco base."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('NutriMill', 'https://nutrimill.com', 'Utah kitchen-appliance brand selling home grain mills, Bosch mixers and accessories; its published affiliate agreement (enrollment via Shopify Collabs) pays a 10% base commission rising to 15% for approved online demonstrators.', 'United States', 'published') returning id into bid;
