  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@nutrimill.com', null, 'https://nutrimill.com/pages/affiliate-agreement', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Shopify Collabs', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://nutrimill.com/pages/affiliate-agreement.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'NutriMill Affiliate Program', null, 'https://nutrimill.com/pages/affiliate-agreement', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nutrimill.com/pages/affiliate-agreement', 'official_site', 'affiliate_program', 'NutriMill''s own published Affiliate Program Agreement (effective September 28, 2026) sets commission tiers: Base 10% for all affiliates, Performance 12% after $20,000 in cumulative verified sales, and Online Demonstrator 15% with written approval, stating ''15% is the maximum rate''. Enrollment and payment run through Shopify Collabs (commissions paid 30 days after the sale), and the agreement publishes the program contact affiliates@nutrimill.com. The 15% figure is a rate ceiling, not an earnings cap; no no-cap statement appears, so the earnings cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nutrimill.com/pages/affiliate-agreement', 'official_site', 'company_profile', 'The agreement is governed by Utah law with arbitration in Washington County, Utah, and covers NutriMill''s home grain mills and Bosch mixer lines, supporting the United States country entry and the home category.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 13, 13, 13, 8, 4, '{"niche_fit": "Grain mills and Bosch mixers fit baking, homestead and from-scratch cooking creators; a focused niche rather than general home.", "ugc_evidence": "The agreement builds in creator mechanics: content and name/likeness rights, product gifting, an affiliate purchasing account and a paid demonstrator tier.", "compensation": "10% base rising to 12% and a 15% maximum for demonstrators is solid for kitchen appliances, with terms published in full.", "contact_access": "A dedicated program email (affiliates@nutrimill.com) is published in the brand''s own agreement.", "opportunity_availability": "Open enrollment through Shopify Collabs for affiliates 18+.", "credibility": "Established US kitchen brand and Bosch mixer distributor with a formal published program agreement."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Spot Pet Insurance', 'https://spotpet.com', 'US pet insurance provider (Spot Pet Insurance Services, Miami, FL) whose referral partner program pays a flat fee per qualified lead generated through a partner''s unique link, and whose affiliate program runs through Impact.', 'United States', 'published') returning id into bid;
