  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 25, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://commissiondex.com/programs/spot-pet-insurance/.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Spot Pet Insurance Referral Partner Program', null, 'https://spotpet.com/spot-referral-partner-terms-and-conditions', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://spotpet.com/spot-referral-partner-terms-and-conditions', 'official_site', 'affiliate_program', 'Spot''s own published Referral Partner Terms state SPOT Pet Insurance Services, Inc. pays partners a lead fee when a referred potential customer submits their first and last name, email and ZIP code through the partner''s unique link; partners must be located in the US and market only to US leads, fees are calculated at month end and paid before the end of the following month, and the terms are governed by Florida law. The footer gives Spot Pet Insurance Services, LLC, 100 Biscayne Blvd, Suite 400, Miami, FL 33132, with plans underwritten by Independence American Insurance Company or United States Fire Insurance Company. The terms do not state the fee amount.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://commissiondex.com/programs/spot-pet-insurance/', 'listing', 'affiliate_program', 'Commissiondex''s program listing reports Spot Pet Insurance pays a flat $25 per lead (pay-per-lead), runs through the Impact network, with a 30-day cookie, $50 minimum payout and monthly payments via PayPal or direct deposit. The recorded rate of 25 is this flat per-lead bounty, not a percentage.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 12, 6, 6, 4, '{"niche_fit": "Pet insurance is a major, recurring topic for pet creators, and Spot is a recognized US provider in that niche.", "ugc_evidence": "The partner model is lead-generation oriented and the brand''s own terms restrict social-media promotion without written consent, so creator evidence is thinner than pet-product brands.", "compensation": "A flat $25 per qualified lead (per directory listing) is reasonable for a short quote form, though it is not a share of policy value.", "contact_access": "Partner terms are public on the brand''s site, but no program email appears on the fetched pages.", "opportunity_availability": "Joinable via Impact and the brand''s partner terms; US-based partners and US leads only.", "credibility": "Licensed US pet insurer based in Miami with policies underwritten by established insurance companies."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lemonade', 'https://www.lemonade.com', 'Licensed digital insurer founded in 2015 in New York selling renters, homeowners, pet, car and term life insurance; its affiliate program runs through Impact and pays flat fees per quote generated.', 'United States', 'published') returning id into bid;
