  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lemonade Affiliate Program', null, 'https://linkclicky.com/affiliate-program/lemonade/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/lemonade/', 'listing', 'affiliate_program', 'LinkClicky''s program profile lists Lemonade''s affiliate platform as Impact with a commission of $15-$20 per quote. Lemonade is a licensed insurer (renters, homeowners, pet, car and term life) founded in 2015 and headquartered in New York.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alanslui.com/best-affiliate-programmes-insurance-finance/', 'listing', 'affiliate_program', 'An insurance-programme comparison checked October 30, 2026 lists ''Lemonade (US pet insurance) — $15-$20 per quote generated, and $0 when the policy is bought'', corroborating the per-quote range for the pet line.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://meersworld.com/insurance-affiliate-programs/', 'review', 'affiliate_program', 'CONFLICT: other directories report different figures — one review lists $15.00 to $35.00 depending on the plan via Impact Radius with a 30-day cookie, and another lists $25.50 per sale. Because published flat payouts conflict ($15-$20 per quote vs $25.50 per sale vs a $15-$35 range), commission_rate is recorded as null rather than guessed.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 11, 6, 8, 5, '{"niche_fit": "Pet insurance is one of Lemonade''s flagship creator-promoted lines and fits pet channels; renters and home lines widen the fit further.", "ugc_evidence": "Directory profiles describe the program as targeting publishers, bloggers and influencers across its insurance lines.", "compensation": "Flat per-quote payouts are reported around $15-$20, but published figures conflict, so the rate is honestly unrecorded and the score reflects the uncertainty.", "contact_access": "Access runs through the Impact application; no public program email appears on the fetched pages.", "opportunity_availability": "Open affiliate program on Impact with broad publisher acceptance.", "credibility": "Publicly traded, licensed US insurer founded in 2015 with a well-known consumer brand."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Lesure', 'https://lesurepet.com', 'Modern pet lifestyle brand founded in 2021 (parent Bedshe International) selling dog and cat beds, travel and hygiene products; it sells heavily through its official TikTok Shop with creator commissions enabled and also lists an affiliate program through Lasso.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'TikTok Shop', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/lesure-bedsure-pet/.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Lesure Pet Affiliate / TikTok Shop Creator Program', null, 'https://getlasso.co/affiliate/lesure-bedsure-pet/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/lesure-bedsure-pet/', 'listing', 'affiliate_program', 'Lasso''s listing for the ''Lesure & Bedsure Pet'' affiliate program reports up to 7.5% commission, a 14-day cookie and a $10 payout threshold. ''Up to 7.5%'' is a ceiling rather than a confirmed base rate, so commission_rate is recorded as null.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.tiktok.com/us/pdp/donut-dog-bed-by-lesure-washable-plush-pet-bed-with-anti-slip-bottom/1729468671204299410?source=product_detail&enter_method=feed_list_recommended_category&first_entrance=product_detail&first_entrance_position=bread_crumbs&first_entrance_tt_scene=seo', 'official_site', 'affiliate_program', 'Lesure''s official TikTok Shop (Lesure Pet, OFFICIAL SHOP, 4.6 rating, roughly 271K-278K units sold, 59K+ followers) sells its pet beds with creator commission videos labelled ''Creator earns commission'', evidencing an active TikTok Shop creator route. Seller information on the shop gives Bedshe International Co LTD, 1057 E Imperial Hwy, Placentia, California 92870, supporting the United States country entry.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.prnewswire.com/news-releases/lesure-brings-human-sleep-standards-to-pets-with-realortho-dog-bed-launch-302828692.html', 'review', 'company_profile', 'A PR Newswire release describes Lesure as a modern pet lifestyle brand founded in 2021, backed by parent Bedshe International, selling across Sleep & Rest, Travel, Smart, Play and Hygiene & Clean, and directs readers to lesurepet.com.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 15, 8, 5, 8, 3, '{"niche_fit": "Pet beds and pet comfort products are a proven TikTok pet niche, and Lesure is a pet-only brand with broad product lines.", "ugc_evidence": "Its official TikTok Shop surfaces creator commission videos on product pages and has sold roughly 271K-278K units, showing active creator selling.", "compensation": "No single published rate: Lasso reports only an up-to-7.5% ceiling and TikTok Shop rates are set per product, so compensation scores low on certainty.", "contact_access": "No public program email or contact appears on the fetched pages.", "opportunity_availability": "TikTok Shop affiliate enrollment is open to creators and a Lasso-listed program route also exists.", "credibility": "Large TikTok sales volume and national retail press coverage, but a young brand (founded 2021) with thin published company detail."}'::jsonb);
